import json

def flood_fill_around_boundary(grid, boundary_value=2, fill_value=1):
    """
    Flood fill from grid edge to mark all cells reachable from boundary.
    Then any remaining unfilled 0 cells are 'inside' a closed loop of boundary values.
    """
    h = len(grid)
    w = len(grid[0])

    # Start with all 0s marked as "unvisited"
    visited = [[False]*w for _ in range(h)]

    # Queue for BFS starting from all boundary cells
    queue = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != boundary_value:
                if r == 0 or r == h-1 or c == 0 or c == w-1:
                    # Edge cell - will be visited first
                    pass

    # Mark reachable cells from edges via BFS
    reachable = [[False]*w for _ in range(h)]

    # Add all non-boundary edge cells to queue
    for r in range(h):
        for c in [0, w-1]:
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] != boundary_value:
                    reachable[r][c] = True
                    queue.append((r, c))

    for c in range(w):
        for r in [0, h-1]:
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] != boundary_value:
                    reachable[r][c] = True
                    queue.append((r, c))

    # Remove duplicates
    unique_queue = list(set(queue))

    # BFS
    import collections
    q = collections.deque(unique_queue)
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not reachable[nr][nc] and grid[nr][nc] != boundary_value:
                    reachable[nr][nc] = True
                    q.append((nr, nc))

    return reachable

