import json

def get_interior_cells(grid):
    """
    Use a proper flood fill from edges to find cells not reachable from boundary.
    These unreachable cells are "interior" - inside a closed loop of non-zero values.
    """
    h = len(grid)
    w = len(grid[0])

    # Start flood fill from all edge cells
    visited = [[False]*w for _ in range(h)]
    stack = []

    # Add all edge cells to stack if they're not the "boundary marker"
    for r in range(h):
        for c in [0, w-1]:
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] != 2:  # Not blocked by 2
                    visited[r][c] = True
                    stack.append((r, c))

    for c in range(w):
        for r in [0, h-1]:
            if 0 <= r < h and 0 <= c < w:
                if not visited[r][c] and grid[r][c] != 2:
                    visited[r][c] = True
                    stack.append((r, c))

    # Remove duplicates and deduplicate stack
    unique_stack = list(set(stack))

    # BFS
    import collections
    q = collections.deque(unique_stack)
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not visited[nr][nc] and grid[nr][nc] != 2:
                    visited[nr][nc] = True
                    q.append((nr, nc))

    return visited

