import json

def flood_fill_reach_edge(grid):
    """
    For each cell, determine if it can reach the grid edge going only through 0s.
    Cells that CANNOT reach the edge are "interior" and should become 1.
    """
    h = len(grid)
    w = len(grid[0])

    # For each starting 0, BFS to see if we can reach edge
    reachable = [[False]*w for _ in range(h)]

    for start_r in range(h):
        for start_c in range(w):
            if grid[start_r][start_c] == 0:
                # BFS from this cell
                visited = set()
                q = [(start_r, start_c)]
                reached_edge = False

                import collections
                queue = collections.deque([(start_r, start_c)])

                while queue:
                    r, c = queue.popleft()

                    if r == 0 or r == h-1 or c == 0 or c == w-1:
                        reached_edge = True
                        break

                    if (r,c) in visited:
                        continue
                    visited.add((r,c))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == 0 and (nr, nc) not in visited:
                                queue.append((nr, nc))

                if reached_edge:
                    reachable[start_r][start_c] = True

    return reachable

