def transform_grid(grid):
    """
    Fill 0s that are STRICTLY between 2s on exactly one axis.
    Along that axis: must have nearest 2s on both sides (exclusive)
    Along perpendicular axis: must NOT have 2s adjacently (u=d=0 for horiz, l=r=0 for vert)
    """
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    # Find cells that fill HORIZONTALLY
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                # Check vertical adjacency first - must have no adjacent 2s
                has_2_up = r > 0 and grid[r-1][c] == 2
                has_2_down = r < h-1 and grid[r+1][c] == 2

                if has_2_up or has_2_down:
                    continue  # Skip if has adjacent 2 vertically

                # Find nearest 2s horizontally
                left_2_pos = None
                right_2_pos = None
                for dc in range(c+1, w):
                    if grid[r][dc] == 2:
                        right_2_pos = dc
                        break
                for dc in range(max(0, c-1)-1, -1, -1):
                    if grid[r][dc] == 2:
                        left_2_pos = dc
                        break

                if left_2_pos is not None and right_2_pos is not None:
                    # Cell is strictly between 2s
                    # Check if there are any other 2s between left_2 and right_2 (exclusive)
                    has_interrupting_2 = False
                    for k in range(left_2_pos+1, right_2_pos):
                        if grid[r][k] == 2:
                            has_interrupting_2 = True
                            break

                    if not has_interrupting_2:
                        # This cell should fill
                        result[r][c] = 1

    # Find cells that fill VERTICALLY  
    for c in range(w):
        for r in range(h):
            if grid[r][c] == 0:
                # Check horizontal adjacency first - must have no adjacent 2s
                has_2_left = c > 0 and grid[r][c-1] == 2
                has_2_right = c < w-1 and grid[r][c+1] == 2

                if has_2_left or has_2_right:
                    continue  # Skip if has adjacent 2 horizontally

                # Find nearest 2s vertically
                up_2_pos = None
                down_2_pos = None
                for dr in range(r+1, h):
                    if grid[dr][c] == 2:
                        down_2_pos = dr
                        break
                for dr in range(max(0, r-1)-1, -1, -1):
                    if grid[dr][c] == 2:
                        up_2_pos = dr
                        break

                if up_2_pos is not None and down_2_pos is not None:
                    # Cell is strictly between 2s
                    # Check if there are any other 2s between up_2 and down_2 (exclusive)
                    has_interrupting_2 = False
                    for k in range(up_2_pos+1, down_2_pos):
                        if grid[k][c] == 2:
                            has_interrupting_2 = True
                            break

                    if not has_interrupting_2:
                        # This cell should fill
                        result[r][c] = 1

    return result

