def transform_grid_correct(grid):
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    # First pass: identify ALL horizontal-bound cells
    # A cell has horizontal bounds if there are 2s on both left and right sides
    horiz_bound = [[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                left_2 = None
                right_2 = None
                for dc in range(c-1, -1, -1):
                    if grid[r][dc] == 2:
                        left_2 = dc
                        break
                for dc in range(c+1, w):
                    if grid[r][dc] == 2:
                        right_2 = dc
                        break
                if left_2 is not None and right_2 is not None:
                    horiz_bound[r][c] = True

    # Second pass: identify ALL vertical-bound cells
    vert_bound = [[False]*w for _ in range(h)]
    for c in range(w):
        for r in range(h):
            if grid[r][c] == 0:
                up_2 = None
                down_2 = None
                for dr in range(r-1, -1, -1):
                    if grid[dr][c] == 2:
                        up_2 = dr
                        break
                for dr in range(r+1, h):
                    if grid[dr][c] == 2:
                        down_2 = dr
                        break
                if up_2 is not None and down_2 is not None:
                    vert_bound[r][c] = True

    # Third pass: for cells bounded HORIZONTALLY
    # Check if there are ANY 2s vertically (anywhere in that column)
    # If NO vertical 2s → fill horizontally!
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and horiz_bound[r][c]:
                # Check entire column for any 2s
                has_vertical_2s = False
                for rr in range(h):
                    if grid[rr][c] == 2:
                        has_vertical_2s = True
                        break

                if not has_vertical_2s:
                    # Also need unobstructed path to edge in perp direction (vertical)
                    # Check both up and down reach edge without 2s
                    can_reach_top = True
                    can_reach_bottom = True

                    nr = r - 1
                    while nr >= 0:
                        if grid[nr][c] == 2:
                            can_reach_top = False
                            break
                        nr -= 1

                    nr = r + 1
                    while nr < h:
                        if grid[nr][c] == 2:
                            can_reach_bottom = False
                            break
                        nr += 1

                    if can_reach_top or can_reach_bottom:
                        result[r][c] = 1

    # Fourth pass: for cells bounded VERTICALLY
    # Check if there are ANY 2s horizontally (anywhere in that row)
    # If NO horizontal 2s → fill vertically!
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and vert_bound[r][c]:
                # Check entire row for any 2s
                has_horizontal_2s = False
                for cc in range(w):
                    if grid[r][cc] == 2:
                        has_horizontal_2s = True
                        break

                if not has_horizontal_2s:
                    # Need unobstructed path to edge in perp direction (horizontal)
                    can_reach_left = True
                    can_reach_right = True

                    nc = c - 1
                    while nc >= 0:
                        if grid[r][nc] == 2:
                            can_reach_left = False
                            break
                        nc -= 1

                    nc = c + 1
                    while nc < w:
                        if grid[r][nc] == 2:
                            can_reach_right = False
                            break
                        nc += 1

                    if can_reach_left or can_reach_right:
                        result[r][c] = 1

    return result

