def transform_grid_v10(grid):
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    # First: identify cells with horizontal bounds (between two 2s in same row)
    horiz_bound = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                left_2 = None
                right_2 = None
                for dc in range(c-1, -1, -1):
                    if grid[r][dc] == 2:
                        left_2 = dc
                        break
                for dc in range(c+1, w):
                    if grid[r][dc] == 2:
                        right_2 = dc
                        break
                if left_2 is not None and right_2 is not None:
                    horiz_bound.add((r, c))

    # Second: identify cells with vertical bounds (between two 2s in same col)
    vert_bound = set()
    for c in range(w):
        for r in range(h):
            if grid[r][c] == 0:
                up_2 = None
                down_2 = None
                for dr in range(r-1, -1, -1):
                    if grid[dr][c] == 2:
                        up_2 = dr
                        break
                for dr in range(r+1, h):
                    if grid[dr][c] == 2:
                        down_2 = dr
                        break
                if up_2 is not None and down_2 is not None:
                    vert_bound.add((r, c))

    # Third: check perp unblocked for each bound cell
    def can_reach_edge(grid, r, c, direction):
        """Check if we can reach grid edge in given direction without hitting 2"""
        nr, nc = r, c
        if direction == 'up':
            while nr > 0:
                nr -= 1
        elif direction == 'down':
            while nr < len(grid) - 1:
                nr += 1
        elif direction == 'left':
            while nc > 0:
                nc -= 1
        else:  # right
            while nc < len(grid[0]) - 1:
                nc += 1

        # Check all cells along path
        start_nr, start_nc = r, c
        if direction == 'up':
            end_nr, end_nc = 0, c
            step = -1
        elif direction == 'down':
            end_nr, end_nc = h-1, c
            step = 1
        elif direction == 'left':
            end_nr, end_nc = r, 0
            step = 0
        else:
            end_nr, end_nc = r, w-1
            step = 0

        curr_r, curr_c = start_nr + step, start_nc + step
        while curr_r != end_nr or curr_c != end_nc:
            if grid[curr_r][curr_c] == 2:
                return False
            curr_r += step
            curr_c += step
        return True

