import json

def transform_grid_v11(grid):
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                # Find closest 2s in each direction
                left_2 = None; right_2 = None; up_2 = None; down_2 = None

                for dc in range(c-1, -1, -1):
                    if grid[r][dc] == 2:
                        left_2 = dc
                        break
                for dc in range(c+1, w):
                    if grid[r][dc] == 2:
                        right_2 = dc
                        break
                for dr in range(r-1, -1, -1):
                    if grid[dr][c] == 2:
                        up_2 = dr
                        break
                for dr in range(r+1, h):
                    if grid[dr][c] == 2:
                        down_2 = dr
                        break

                horiz_bounds = (left_2 is not None and right_2 is not None)
                vert_bounds = (up_2 is not None and down_2 is not None)

                if horiz_bounds:
                    # Check perp (vertical) clearance
                    can_go_up = True
                    can_go_down = True

                    nr = r - 1
                    while nr >= 0:
                        if grid[nr][c] == 2:
                            can_go_up = False
                            break
                        nr -= 1

                    nr = r + 1
                    while nr < h:
                        if grid[nr][c] == 2:
                            can_go_down = False
                            break
                        nr += 1

                    if can_go_up and can_go_down:
                        result[r][c] = 1

                elif vert_bounds:
                    # Check perp (horizontal) clearance
                    can_go_left = True
                    can_go_right = True

                    nc = c - 1
                    while nc >= 0:
                        if grid[r][nc] == 2:
                            can_go_left = False
                            break
                        nc -= 1

                    nc = c + 1
                    while nc < w:
                        if grid[r][nc] == 2:
                            can_go_right = False
                            break
                        nc += 1

                    if can_go_left and can_go_right:
                        result[r][c] = 1

    return result

